function toMd(headers, rows){
  var h='| '+headers.join(' | ')+' |';
  var sep='| '+headers.map(function(){return '---';}).join(' | ')+' |';
  var body=rows.map(function(r){ return '| '+r.join(' | ')+' |'; }).join('\n');
  return h+'\n'+sep+'\n'+body;
}
function fromMd(md){
  var lines=md.trim().split(/\r?\n/).filter(function(l){return l.trim()!=='';});
  function cells(l){ return l.replace(/^\|/,'').replace(/\|$/,'').split('|').map(function(c){return c.trim();}); }
  return {headers:cells(lines[0]), rows:lines.slice(2).map(cells)};
}
var EXPORTS={toMd:toMd, fromMd:fromMd};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MarkdownTableForgePure = EXPORTS; }
